__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"default",{enumerable:!0,get:function(){return o}});var t=r(d[0]),c=r(d[1]),n=r(d[2]),s=r(d[3]);function o(){const{doc:o}=(0,t.useLocalSearchParams)(),l='terms'!==o;return(0,s.jsxs)(c.Screen,{children:[(0,s.jsx)(t.Stack.Screen,{options:{title:l?'Privacy Policy':'Terms of Use'}}),(0,s.jsx)(c.Text,{variant:"title",children:l?'Privacy Policy':'Terms of Use'}),(0,s.jsxs)(c.Text,{variant:"caption",muted:!0,children:["Last updated ",n.LAST_UPDATED]}),(0,s.jsx)(c.Text,{selectable:!0,children:l?n.privacy:n.terms})]})}},776,[782,808,849,6]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"LAST_UPDATED",{enumerable:!0,get:function(){return n}}),Object.defineProperty(e,"privacy",{enumerable:!0,get:function(){return o}}),Object.defineProperty(e,"terms",{enumerable:!0,get:function(){return t}});const n='21 November 2026',o="Paisa Kidhar (\"we\") is operated by WinPlayBox, Mumbai, India. This policy explains what we collect and why.\n\nWHAT WE COLLECT\n\u2022 Account: your name, email address, an automatically created username, and a password (stored hashed by our authentication provider) \u2014 or your Google account's name and email if you sign in with Google.\n\u2022 Registry: partner names, optional wedding date, city and story, the goals you create, and the UPI ID you choose to show guests.\n\u2022 Gifts: for each gift a guest starts \u2014 amount, goal, optional name and message, whether they chose anonymous, a payment reference, and a one-way hashed IP address used only for abuse prevention.\n\u2022 Premium purchases: order status and amount. Card/UPI details are entered on Dodo Payments' checkout and never reach us.\n\u2022 Usage: a small set of product events (for example \"registry published\") without personal content.\n\u2022 Ads (only if enabled): Google AdMob may use your device's advertising ID according to the consent you give in the app. Premium registries never show ads.\n\nWHAT WE DON'T DO\n\u2022 We never hold, move or store guests' money. Gifts go directly from the guest's UPI app to the couple's UPI ID.\n\u2022 We never see UPI PINs, bank or card details.\n\u2022 We don't sell personal data.\n\nWHO PROCESSES DATA FOR US\nSupabase (database & sign-in), Render (API hosting), Google (sign-in; AdMob if enabled), Dodo Payments (Premium checkout, merchant of record). Data may be processed outside India by these providers.\n\nWHO CAN SEE WHAT\n\u2022 Anyone with your registry link sees your names, date, city, story, public goals, progress (if you turn it on) and confirmed blessings. Anonymous givers' names are never shown publicly.\n\u2022 Only you see guest names on anonymous gifts, amounts, references and unconfirmed gifts.\n\u2022 Private goals are visible only to you.\n\nYOUR CHOICES\nEdit or remove anything in the app. Delete your account in Profile \u2192 Delete my account: your registries are hidden immediately and your data is erased within 30 days, except records we must keep by law (for example Premium invoices).\n\nCHILDREN\nPaisa Kidhar is for adults (18+).\n\nCONTACT\nsupport@winplaybox.in \u2014 Grievance officer: Sagar, WinPlayBox, Mumbai, Maharashtra, India. We respond within 30 days.",t="By using Paisa Kidhar you agree to these terms.\n\n1. WHAT PAISA KIDHAR IS\nA tool for couples to publish wedding \"dream\" goals and for guests to send gifts directly to the couple's UPI ID. We are not a bank, wallet, escrow, payment aggregator or crowdfunding platform, and we never receive or hold gift money.\n\n2. GIFTS\nGifts are voluntary personal transfers between a guest and the couple, made in the guest's own UPI app. Whether a gift arrived is confirmed by the couple. Refunds of gifts are between the guest and the couple. We can't reverse UPI transfers.\n\n3. COUPLES' RESPONSIBILITIES\nUse your own UPI ID, tell the truth about your wedding and goals, don't use Paisa Kidhar for fundraising unrelated to your wedding, for business sales, or for anything illegal. We may hide registries that break these rules.\n\n4. PREMIUM\nPremium Registry is a one-time digital purchase for one registry, sold through Dodo Payments as merchant of record. Prices include applicable taxes as shown at checkout. If Premium features don't work for you, email support@winplaybox.in within 7 days of purchase for a refund.\n\n5. AVAILABILITY\nWe work hard to keep the service running but provide it \"as is\". To the extent permitted by law, our liability is limited to the amount you paid us in the last 12 months.\n\n6. CHANGES & LAW\nWe'll notify you in the app before material changes. These terms are governed by the laws of India; courts in Mumbai have jurisdiction.\n\nContact: support@winplaybox.in"},849,[]);